param([int]$HttpPort = 8765)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System
Add-Type -AssemblyName System.Core
$script:state = [ordered]@{ status='getrennt'; error=''; config=$null; queue=0; events=(New-Object System.Collections.ArrayList); traffic=@{poll=@{rx=0;tx=0};ack=@{rx=0;tx=0};eot=@{rx=0;tx=0};block=@{rx=0;tx=0};error=@{rx=0;tx=0}} }
$script:rxbuf = New-Object System.Collections.Generic.List[byte]
$script:serial = $null; $script:tcp = $null; $script:tcpServer = $null; $script:client = $null
function Add-Event($direction,$kind,[byte[]]$raw,$extra) {
  $cat = if($kind -in @('poll','select')){'poll'} elseif($kind -in @('ack','block_reply')){'ack'} elseif($kind -in @('eot','empty_poll')){'eot'} elseif($kind -eq 'block'){'block'} else {'error'}
  if($direction -in @('rx','tx')){$script:state.traffic[$cat][$direction]++}
  $hex=($raw|%{$_.ToString('X2')}) -join ' '
  $entry=[ordered]@{id=([int]$script:state.lastId+1);time=(Get-Date).ToString('yyyy-MM-ddTHH:mm:ss.fffK');direction=$direction;kind=$kind;category=$cat;keepalive=($kind -in @('poll','select','ack','eot','empty_poll'));hex=$hex}
  if($extra){foreach($k in $extra.Keys){$entry[$k]=$extra[$k]}}
  [void]$script:state.events.Add($entry);$script:state.lastId=$entry.id
  while($script:state.events.Count -gt 500){$script:state.events.RemoveAt(0)}
}
function Decode-Bytes([byte[]]$bytes){foreach($b in $bytes){$script:rxbuf.Add($b)};while($script:rxbuf.Count){$n=$script:rxbuf.Count
  if($script:rxbuf[0] -eq 1){$end=-1;for($i=1;$i -lt $n;$i++){if($script:rxbuf[$i] -eq 3){$end=$i;break}};if($end -lt 0 -or $n -lt $end+2){break};$raw=$script:rxbuf.GetRange(0,$end+2).ToArray();$script:rxbuf.RemoveRange(0,$end+2);$x=0;for($i=1;$i -le $end;$i++){$x=$x -bxor $raw[$i]};$ok=(($x -band 127) -eq $raw[$end+1]);$txt=[Text.Encoding]::ASCII.GetString($raw);$kind=if($ok){'block'}else{'error'};Add-Event rx $kind $raw @{summary=$txt;bcc_ok=$ok};continue}
  if($n -ge 2 -and $script:rxbuf[0] -ge 48 -and $script:rxbuf[0] -le 57 -and $script:rxbuf[1] -eq 5){$raw=$script:rxbuf.GetRange(0,2).ToArray();$script:rxbuf.RemoveRange(0,2);Add-Event rx poll $raw @{address=[char]$raw[0]};continue}
  $b=$script:rxbuf[0];if($b -in @(4,6,21)){ $script:rxbuf.RemoveAt(0);$kind=@{4='eot';6='ack';21='nak'}[$b];Add-Event rx $kind ([byte[]]@($b)) @{};continue};if($n -eq 1){break};$script:rxbuf.RemoveAt(0);Add-Event rx unknown ([byte[]]@($b)) @{}
}}
function Read-Transport {try {if($script:serial -and $script:serial.IsOpen -and $script:serial.BytesToRead -gt 0){$buf=New-Object byte[] ([Math]::Min(4096,$script:serial.BytesToRead));$n=$script:serial.Read($buf,0,$buf.Length);if($n){Decode-Bytes $buf[0..($n-1)]}};if($script:client -and $script:client.Connected -and $script:client.Available -gt 0){$buf=New-Object byte[] ([Math]::Min(4096,$script:client.Available));$n=$script:client.GetStream().Read($buf,0,$buf.Length);if($n){Decode-Bytes $buf[0..($n-1)]}};if($script:tcpServer -and -not $script:client -and $script:tcpServer.Pending()){$script:client=$script:tcpServer.AcceptTcpClient();$script:client.ReceiveTimeout=100}}catch{$script:state.error=$_.Exception.Message;$script:state.status='Fehler'}}
function Stop-Link {try{if($script:serial){$script:serial.Close();$script:serial.Dispose()};if($script:client){$script:client.Close()};if($script:tcpServer){$script:tcpServer.Stop()};if($script:tcp){$script:tcp.Close()}}catch{};$script:serial=$null;$script:client=$null;$script:tcpServer=$null;$script:tcp=$null;$script:state.status='getrennt';Add-Event system stop ([byte[]]@()) @{} }
function Write-Link([byte[]]$bytes){if($script:serial){$script:serial.Write($bytes,0,$bytes.Length)}elseif($script:client){$script:client.GetStream().Write($bytes,0,$bytes.Length)}else{throw 'Keine verbundene Gegenstelle'};Add-Event tx manual $bytes @{} }
function Start-Link($c){Stop-Link;$script:state.error='';$script:state.config=$c;if($c.transport -eq 'serial'){$parityEnum=switch($c.parity){'E'{[IO.Ports.Parity]::Even}'O'{[IO.Ports.Parity]::Odd}default{[IO.Ports.Parity]::None}};$stopEnum=if([int]$c.stops -eq 2){[IO.Ports.StopBits]::Two}else{[IO.Ports.StopBits]::One};$script:serial=[IO.Ports.SerialPort]::new($c.serial_port,[int]$c.baud,$parityEnum,[int]$c.bits,$stopEnum);$script:serial.ReadTimeout=50;$script:serial.Open()}elseif($c.transport -eq 'tcp_client'){$script:client=New-Object Net.Sockets.TcpClient;$script:client.Connect($c.host,[int]$c.port);$script:client.ReceiveTimeout=100}else{$script:tcpServer=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Parse($c.host),[int]$c.port);$script:tcpServer.Start()};$script:state.status=if($c.transport -eq 'tcp_listen'){'wartet auf TCP-Verbindung'}else{'verbunden'};Add-Event system start ([byte[]]@()) @{info=$c}}
function Reply($stream,$status,$content,$type='application/json; charset=utf-8'){$bytes=[Text.Encoding]::UTF8.GetBytes($content);$head=[Text.Encoding]::ASCII.GetBytes("HTTP/1.1 $status`r`nContent-Type: $type`r`nContent-Length: $($bytes.Length)`r`nConnection: close`r`nCache-Control: no-store`r`n`r`n");$stream.Write($head,0,$head.Length);$stream.Write($bytes,0,$bytes.Length)}
$listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,$HttpPort);$listener.Start();$url="http://127.0.0.1:$HttpPort/";Write-Host "FreeESPA läuft lokal: $url" -ForegroundColor Cyan;Start-Job {Start-Sleep -Milliseconds 800;Start-Process $using:url}|Out-Null
try {while($true){Read-Transport;if(-not $listener.Pending()){Start-Sleep -Milliseconds 20;continue};$clientHttp=$listener.AcceptTcpClient();$stream=$clientHttp.GetStream();$stream.ReadTimeout=3000;try{$reader=New-Object IO.StreamReader($stream,[Text.Encoding]::UTF8,$false,4096,$true);$request=$reader.ReadLine();$headers=@{};while(($line=$reader.ReadLine()) -and $line -ne ''){$p=$line.IndexOf(':');if($p -gt 0){$headers[$line.Substring(0,$p).ToLower()]=$line.Substring($p+1).Trim()}};$length=0;if($headers.ContainsKey('content-length')){$length=[int]$headers['content-length']};$body='';if($length -gt 0){$buf=New-Object char[] $length;[void]$reader.ReadBlock($buf,0,$length);$body=-join $buf};$parts=$request.Split(' ');$method=$parts[0];$path=$parts[1].Split('?')[0];$result=$null
 if($method -eq 'GET' -and $path -eq '/'){$file=Join-Path $PSScriptRoot 'index.html';Reply $stream '200 OK' ([IO.File]::ReadAllText($file)) 'text/html; charset=utf-8'}
 elseif($method -eq 'GET' -and $path -eq '/api/state'){Reply $stream '200 OK' (ConvertTo-Json -InputObject $script:state -Depth 12 -Compress)}
 elseif($method -eq 'GET' -and $path -eq '/api/ports'){$ports=@([IO.Ports.SerialPort]::GetPortNames()|%{@{path=$_;label=$_}});Reply $stream '200 OK' (ConvertTo-Json -InputObject $ports -Compress)}
 elseif($method -eq 'POST'){$data=if($body){ConvertFrom-Json $body}else{@{}};switch($path){'/api/start'{Start-Link $data;$result=@{ok=$true}}'/api/stop'{Stop-Link;$result=@{ok=$true}}'/api/reset'{$script:state.events.Clear();foreach($k in $script:state.traffic.Keys){$script:state.traffic[$k].rx=0;$script:state.traffic[$k].tx=0};$result=@{ok=$true}}'/api/send'{$result=@{ok=$false;error='Meldungseditor wird im nächsten Schritt ergänzt'}}'/api/raw'{$hex=$data.hex -replace '[^0-9A-Fa-f]','';if($hex.Length -eq 0 -or ($hex.Length%2)){throw 'Hexdaten ungültig'};$raw=New-Object byte[] ($hex.Length/2);for($i=0;$i -lt $raw.Length;$i++){$raw[$i]=[Convert]::ToByte($hex.Substring($i*2,2),16)};Write-Link $raw;$result=@{ok=$true;hex=$data.hex}}default{$result=@{ok=$false;error='Unbekannter API-Pfad'}}};$status=if($result.ok){'200 OK'}else{'400 Bad Request'};Reply $stream $status (ConvertTo-Json $result -Compress)}
 else{Reply $stream '404 Not Found' 'Not found' 'text/plain; charset=utf-8'}
 }catch{try{Reply $stream '400 Bad Request' (ConvertTo-Json @{ok=$false;error=$_.Exception.Message} -Compress)}catch{}}finally{$stream.Dispose();$clientHttp.Close()}}
}finally{Stop-Link;$listener.Stop()}
